#define TX_SOURCE_CODE

#include "tx_api.h"
#include "txm_module.h"


/* Define the ways a caller-supplied range can sit relative to the module's data region.  */

#define TXM_MODULE_DATA_WINDOW_OUTSIDE      0           /* No byte touches the data mapping.    */
#define TXM_MODULE_DATA_WINDOW_CONTAINED    1           /* Every byte is recorded module data.  */
#define TXM_MODULE_DATA_WINDOW_PARTIAL      2           /* Some, but not all, bytes are.        */


/* Define the page mask derived from the smallest MMU page this port maps.  */

#define TXM_MODULE_PAGE_OFFSET_MASK         ((ALIGN_TYPE) (TXM_MODULE_MEMORY_ALIGNMENT - 1))
#define TXM_MODULE_PAGE_BASE_MASK           (~TXM_MODULE_PAGE_OFFSET_MASK)


/**************************************************************************/
/*                                                                        */
/*  FUNCTION                                               RELEASE        */
/*                                                                        */
/*    _txm_module_manager_range_end_get               Cortex-A7/MMU/IAR   */
/*                                                           6.5.0        */
/*  AUTHOR                                                                */
/*                                                                        */
/*    Eclipse ThreadX contributors                                        */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    This function derives the inclusive address of the last byte of a   */
/*    caller-supplied range. An empty range is rejected, matching the     */
/*    portable check macros, and so is a range whose last byte is not     */
/*    representable, so that no caller ever works from a wrapped address. */
/*                                                                        */
/*  INPUT                                                                 */
/*                                                                        */
/*    obj_ptr                           Address of the first byte         */
/*    obj_size                          Size of the range in bytes        */
/*    last_byte                         Destination for the last address  */
/*                                                                        */
/*  OUTPUT                                                                */
/*                                                                        */
/*    TX_TRUE if the range is non-empty and does not wrap                 */
/*                                                                        */
/*  CALLS                                                                 */
/*                                                                        */
/*    None                                                                */
/*                                                                        */
/*  CALLED BY                                                             */
/*                                                                        */
/*    _txm_module_manager_inside_data_check                               */
/*    _txm_module_manager_outside_data_check                              */
/*                                                                        */
/*  RELEASE HISTORY                                                       */
/*                                                                        */
/*    DATE              NAME                      DESCRIPTION             */
/*                                                                        */
/*  08-24-2026      Eclipse ThreadX         Initial Version 6.5.0         */
/*                    contributors                                        */
/*                                                                        */
/**************************************************************************/
static UINT  _txm_module_manager_range_end_get(ALIGN_TYPE obj_ptr, ULONG obj_size, ALIGN_TYPE *last_byte)
{

ALIGN_TYPE  span;
ALIGN_TYPE  highest;
UINT        status;


    /* Assume the range cannot be used until proven otherwise.  */
    status =  TX_FALSE;

    /* An empty range has no last byte and is rejected, just as the portable macros do.  */
    if (obj_size != ((ULONG) 0))
    {

        /* Work with the inclusive span so that a range reaching the top of the address
           space stays representable.  */
        span =  ((ALIGN_TYPE) obj_size) - ((ALIGN_TYPE) 1);

        /* Determine the highest first byte this span can start from.  */
        highest =  (~((ALIGN_TYPE) 0)) - span;

        /* Determine if the range would run past the end of the address space.  */
        if (obj_ptr <= highest)
        {

            /* Record the last byte of the range.  */
            *last_byte =  obj_ptr + span;

            /* The range is usable.  */
            status =  TX_TRUE;
        }
    }

    /* Return the completion status.  */
    return(status);
}


/**************************************************************************/
/*                                                                        */
/*  FUNCTION                                               RELEASE        */
/*                                                                        */
/*    _txm_module_manager_data_window_classify        Cortex-A7/MMU/IAR   */
/*                                                           6.5.0        */
/*  AUTHOR                                                                */
/*                                                                        */
/*    Eclipse ThreadX contributors                                        */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    This function reports how a range sits relative to the module's own */
/*    data region. The module manager records that region exactly, while  */
/*    the MMU can only map it a page at a time, so the mapping may reach  */
/*    past the recorded end. The recorded region therefore stays the      */
/*    authority for the whole mapped window: a range that leaves the      */
/*    recorded region but still lands in the window is reported as        */
/*    partial, and its caller rejects it rather than asking the MMU,      */
/*    which would accept the rounding slack.                              */
/*                                                                        */
/*  INPUT                                                                 */
/*                                                                        */
/*    module_instance                   Pointer to module instance        */
/*    first_byte                        Address of the first byte         */
/*    last_byte                         Address of the last byte          */
/*                                                                        */
/*  OUTPUT                                                                */
/*                                                                        */
/*    One of the TXM_MODULE_DATA_WINDOW_* classifications                 */
/*                                                                        */
/*  CALLS                                                                 */
/*                                                                        */
/*    None                                                                */
/*                                                                        */
/*  CALLED BY                                                             */
/*                                                                        */
/*    _txm_module_manager_inside_data_check                               */
/*    _txm_module_manager_outside_data_check                              */
/*                                                                        */
/*  RELEASE HISTORY                                                       */
/*                                                                        */
/*    DATE              NAME                      DESCRIPTION             */
/*                                                                        */
/*  08-24-2026      Eclipse ThreadX         Initial Version 6.5.0         */
/*                    contributors                                        */
/*                                                                        */
/**************************************************************************/
static UINT  _txm_module_manager_data_window_classify(TXM_MODULE_INSTANCE *module_instance, ALIGN_TYPE first_byte, ALIGN_TYPE last_byte)
{

ALIGN_TYPE  data_start;
ALIGN_TYPE  data_end;
ALIGN_TYPE  window_start;
ALIGN_TYPE  window_end;
UINT        window;


    /* Pick up the recorded data region. The end address is inclusive.  */
    data_start =  (ALIGN_TYPE) module_instance -> txm_module_instance_data_start;
    data_end =    (ALIGN_TYPE) module_instance -> txm_module_instance_data_end;

    /* Determine if the module has a usable data region at all.  */
    if (data_start > data_end)
    {

        /* An unset or inverted region owns nothing.  */
        window =  TXM_MODULE_DATA_WINDOW_OUTSIDE;
    }
    else
    {

        /* Widen the region to the pages the MMU actually maps for it.  */
        window_start =  data_start & TXM_MODULE_PAGE_BASE_MASK;
        window_end =    data_end | TXM_MODULE_PAGE_OFFSET_MASK;

        /* Determine if every byte is recorded module data.  */
        if ((first_byte >= data_start) && (last_byte <= data_end))
        {

            /* The whole range belongs to the module.  */
            window =  TXM_MODULE_DATA_WINDOW_CONTAINED;
        }
        else if ((first_byte <= window_end) && (last_byte >= window_start))
        {

            /* The range overlaps the mapped window without being contained by the
               recorded region, so it leaves the module's data partway through.  */
            window =  TXM_MODULE_DATA_WINDOW_PARTIAL;
        }
        else
        {

            /* The range lies elsewhere, so only the MMU can speak for it.  */
            window =  TXM_MODULE_DATA_WINDOW_OUTSIDE;
        }
    }

    /* Return the classification.  */
    return(window);
}


/**************************************************************************/
/*                                                                        */
/*  FUNCTION                                               RELEASE        */
/*                                                                        */
/*    _txm_module_manager_page_walk                   Cortex-A7/MMU/IAR   */
/*                                                           6.5.0        */
/*  AUTHOR                                                                */
/*                                                                        */
/*    Eclipse ThreadX contributors                                        */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    This function translates every page a range touches and reports     */
/*    whether all of them answered as expected. The walk stops at the     */
/*    first page that disagrees, and a range spanning more pages than     */
/*    the configured maximum is refused so that one kernel request can    */
/*    never impose unbounded work.                                        */
/*                                                                        */
/*  INPUT                                                                 */
/*                                                                        */
/*    first_byte                        Address of the first byte         */
/*    last_byte                         Address of the last byte          */
/*    write_request                     Access intent to translate for    */
/*    expected                          Result every page must return     */
/*                                                                        */
/*  OUTPUT                                                                */
/*                                                                        */
/*    TX_TRUE if every page answered as expected                          */
/*                                                                        */
/*  CALLS                                                                 */
/*                                                                        */
/*    _txm_module_manager_address_probe                                   */
/*                                                                        */
/*  CALLED BY                                                             */
/*                                                                        */
/*    _txm_module_manager_inside_data_check                               */
/*    _txm_module_manager_outside_data_check                              */
/*                                                                        */
/*  RELEASE HISTORY                                                       */
/*                                                                        */
/*    DATE              NAME                      DESCRIPTION             */
/*                                                                        */
/*  08-24-2026      Eclipse ThreadX         Initial Version 6.5.0         */
/*                    contributors                                        */
/*                                                                        */
/**************************************************************************/
static UINT  _txm_module_manager_page_walk(ALIGN_TYPE first_byte, ALIGN_TYPE last_byte, UINT write_request, UINT expected)
{

ALIGN_TYPE  first_page;
ALIGN_TYPE  last_page;
ALIGN_TYPE  page;
ULONG       pages;
ULONG       index;
UINT        matched;


    /* Reduce the range to the pages it touches.  */
    first_page =  first_byte & TXM_MODULE_PAGE_BASE_MASK;
    last_page =   last_byte & TXM_MODULE_PAGE_BASE_MASK;

    /* Count them. Both addresses are page-aligned, so the division is exact.  */
    pages =  ((ULONG) ((last_page - first_page) / ((ALIGN_TYPE) TXM_MODULE_MEMORY_ALIGNMENT))) + ((ULONG) 1);

    /* Determine if the range is longer than this port is willing to translate.  */
    if (pages > ((ULONG) TXM_MODULE_MANAGER_DATA_CHECK_MAX_PAGES))
    {

        /* Refuse rather than spend unbounded time in a kernel request. Refusing is safe
           for both callers: neither can then claim the range is inside or outside.  */
        matched =  TX_FALSE;
    }
    else
    {

        /* Assume every page agrees until one does not.  */
        matched =  TX_TRUE;
        index =    (ULONG) 0;

        /* Translate each page in turn, stopping as soon as the answer is settled. The
           address is rebuilt from the index so that the walk cannot wrap past the top
           page of the address space.  */
        while ((index < pages) && (matched == TX_TRUE))
        {

            /* Build the address of this page.  */
            page =  first_page + (((ALIGN_TYPE) index) * ((ALIGN_TYPE) TXM_MODULE_MEMORY_ALIGNMENT));

            /* Ask the MMU whether the module may reach this page with the requested access.  */
            if (_txm_module_manager_address_probe((ULONG) page, write_request) != expected)
            {

                /* This page disagrees, so the range as a whole does.  */
                matched =  TX_FALSE;
            }

            /* Move to the next page.  */
            index++;
        }
    }

    /* Return whether the whole range answered as expected.  */
    return(matched);
}


/**************************************************************************/
/*                                                                        */
/*  FUNCTION                                               RELEASE        */
/*                                                                        */
/*    _txm_module_manager_inside_data_check           Cortex-A7/MMU/IAR   */
/*                                                           6.5.0        */
/*  AUTHOR                                                                */
/*                                                                        */
/*    Eclipse ThreadX contributors                                        */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    This function determines whether every byte of a caller-supplied    */
/*    range lies inside the module's data or shared memory and is         */
/*    reachable by the module with the requested access. The module's own */
/*    data region is answered from the manager's own records, which are   */
/*    exact. Anything else is answered by translating every page the      */
/*    range touches, because this port keeps no record of the shared and  */
/*    external regions the application maps into the module.              */
/*                                                                        */
/*  INPUT                                                                 */
/*                                                                        */
/*    module_instance                   Pointer to module instance        */
/*    obj_ptr                           Address of the first byte         */
/*    obj_size                          Size of the range in bytes        */
/*    write_request                     TXM_MODULE_MANAGER_ACCESS_READ or */
/*                                        TXM_MODULE_MANAGER_ACCESS_WRITE */
/*                                                                        */
/*  OUTPUT                                                                */
/*                                                                        */
/*    TX_TRUE if the whole range is reachable with that access            */
/*                                                                        */
/*  CALLS                                                                 */
/*                                                                        */
/*    _txm_module_manager_range_end_get                                   */
/*    _txm_module_manager_current_asid_get                                */
/*    _txm_module_manager_data_window_classify                            */
/*    _txm_module_manager_page_walk                                       */
/*                                                                        */
/*  CALLED BY                                                             */
/*                                                                        */
/*    TXM_MODULE_MANAGER_CHECK_INSIDE_DATA_READ                           */
/*    TXM_MODULE_MANAGER_CHECK_INSIDE_DATA_WRITE                          */
/*                                                                        */
/*  RELEASE HISTORY                                                       */
/*                                                                        */
/*    DATE              NAME                      DESCRIPTION             */
/*                                                                        */
/*  08-24-2026      Eclipse ThreadX         Initial Version 6.5.0         */
/*                    contributors                                        */
/*                                                                        */
/**************************************************************************/
UINT  _txm_module_manager_inside_data_check(TXM_MODULE_INSTANCE *module_instance, ALIGN_TYPE obj_ptr, ULONG obj_size, UINT write_request)
{

ALIGN_TYPE  last_byte;
UINT        window;
UINT        status;


    /* Assume the range is not usable until every condition is met.  */
    status =  TX_FALSE;

    /* A range can only belong to a module that exists.  */
    if (module_instance != TX_NULL)
    {

        /* Determine the last byte, rejecting empty and wrapping ranges.  */
        if (_txm_module_manager_range_end_get(obj_ptr, obj_size, &last_byte) == TX_TRUE)
        {

            /* Address translation answers for whichever context is loaded, so it can only
               be trusted while the requesting module's context is the loaded one.  */
            if (_txm_module_manager_current_asid_get() == (module_instance -> txm_module_instance_asid))
            {

                /* Place the range relative to the module's own data region.  */
                window =  _txm_module_manager_data_window_classify(module_instance, obj_ptr, last_byte);

                if (window == ((UINT) TXM_MODULE_DATA_WINDOW_CONTAINED))
                {

                    /* The module's data region is mapped for unprivileged reading and
                       writing, so both intents are satisfied without translating.  */
                    status =  TX_TRUE;
                }
                else if (window == ((UINT) TXM_MODULE_DATA_WINDOW_OUTSIDE))
                {

                    /* Shared or external memory: every page must grant the access.  */
                    status =  _txm_module_manager_page_walk(obj_ptr, last_byte, write_request, TX_TRUE);
                }
                else
                {

                    /* The range leaves the module's data partway through.  */
                    status =  TX_FALSE;
                }
            }
        }
    }

    /* Return the completion status.  */
    return(status);
}


/**************************************************************************/
/*                                                                        */
/*  FUNCTION                                               RELEASE        */
/*                                                                        */
/*    _txm_module_manager_outside_data_check          Cortex-A7/MMU/IAR   */
/*                                                           6.5.0        */
/*  AUTHOR                                                                */
/*                                                                        */
/*    Eclipse ThreadX contributors                                        */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    This function determines whether no byte of a caller-supplied range */
/*    is reachable by the module. It is deliberately not the negation of  */
/*    the inside check: a range that reaches into the module's memory      */
/*    only partway is inside neither answer, and reporting it as outside  */
/*    would let it pass as a kernel object.                               */
/*                                                                        */
/*  INPUT                                                                 */
/*                                                                        */
/*    module_instance                   Pointer to module instance        */
/*    obj_ptr                           Address of the first byte         */
/*    obj_size                          Size of the range in bytes        */
/*                                                                        */
/*  OUTPUT                                                                */
/*                                                                        */
/*    TX_TRUE if no byte of the range is reachable by the module          */
/*                                                                        */
/*  CALLS                                                                 */
/*                                                                        */
/*    _txm_module_manager_range_end_get                                   */
/*    _txm_module_manager_current_asid_get                                */
/*    _txm_module_manager_data_window_classify                            */
/*    _txm_module_manager_page_walk                                       */
/*                                                                        */
/*  CALLED BY                                                             */
/*                                                                        */
/*    TXM_MODULE_MANAGER_CHECK_OUTSIDE_DATA                               */
/*                                                                        */
/*  RELEASE HISTORY                                                       */
/*                                                                        */
/*    DATE              NAME                      DESCRIPTION             */
/*                                                                        */
/*  08-24-2026      Eclipse ThreadX         Initial Version 6.5.0         */
/*                    contributors                                        */
/*                                                                        */
/**************************************************************************/
UINT  _txm_module_manager_outside_data_check(TXM_MODULE_INSTANCE *module_instance, ALIGN_TYPE obj_ptr, ULONG obj_size)
{

ALIGN_TYPE  last_byte;
UINT        window;
UINT        status;


    /* Assume the range is not provably outside the module.  */
    status =  TX_FALSE;

    /* A range can only be placed against a module that exists.  */
    if (module_instance != TX_NULL)
    {

        /* Determine the last byte, rejecting empty and wrapping ranges.  */
        if (_txm_module_manager_range_end_get(obj_ptr, obj_size, &last_byte) == TX_TRUE)
        {

            /* Address translation answers for whichever context is loaded, so it can only
               be trusted while the requesting module's context is the loaded one.  */
            if (_txm_module_manager_current_asid_get() == (module_instance -> txm_module_instance_asid))
            {

                /* Place the range relative to the module's own data region.  */
                window =  _txm_module_manager_data_window_classify(module_instance, obj_ptr, last_byte);

                if (window == ((UINT) TXM_MODULE_DATA_WINDOW_OUTSIDE))
                {

                    /* Clear of the module's data region, so the remaining question is
                       whether any page of it is shared or external memory.  */
                    status =  _txm_module_manager_page_walk(obj_ptr, last_byte, TXM_MODULE_MANAGER_ACCESS_READ, TX_FALSE);
                }
                else
                {

                    /* The range touches the module's data region.  */
                    status =  TX_FALSE;
                }
            }
        }
    }

    /* Return the completion status.  */
    return(status);
}
